package variablelengthquantity

import "errors"

const continueBit = 0x80

// EncodeVarint encodes each uint32 as a variable length quantity.
// Each value is split into 7-bit groups; the most significant group is
// emitted first. Every byte except the last carries the continue bit.
func EncodeVarint(input []uint32) []byte {
	var out []byte
	for _, v := range input {
		// Find the most significant non-zero 7-bit group.
		shift := uint(28)
		for shift > 0 && (v>>shift)&0x7f == 0 {
			shift -= 7
		}
		for {
			group := byte((v >> shift) & 0x7f)
			if shift == 0 {
				out = append(out, group)
				break
			}
			out = append(out, group|continueBit)
			shift -= 7
		}
	}
	return out
}

// DecodeVarint decodes a variable length quantity byte stream back into
// uint32 values. It returns an error if the stream ends with a byte that
// still has the continue bit set (an incomplete sequence).
func DecodeVarint(input []byte) ([]uint32, error) {
	var out []uint32
	var v uint32
	for _, b := range input {
		v = v<<7 | uint32(b&0x7f)
		if b&continueBit == 0 {
			out = append(out, v)
			v = 0
		}
	}
	if len(input) > 0 && input[len(input)-1]&continueBit != 0 {
		return nil, errors.New("incomplete sequence")
	}
	return out, nil
}
